-- The MULTI-MASTER code key (Code keys -> Milling -> MULTI-MASTER), from the ISCAR
-- milling catalog and e-catalog's MULTI-MASTER families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.multimastermill', $ck${"title": "MULTI-MASTER code key – milling heads, shanks and extensions", "subtitle": "Interchangeable solid carbide milling heads on the MULTI-MASTER threaded connection, the shanks, adaptations and extensions that carry them; drilling, chamfering and centering heads are in Code keys -> Drilling -> MULTI-MASTER", "example": "MM EC100A07R1.0-4T06", "decoder": "multi-master-mill", "sections": [{"key": "t-family", "title": "Head – family", "sample": "EC", "rows": [{"code": "EC", "meaning": "Endmill heads (3, 4, 6, 8, 10 flutes; CF: CHATTER-FREE; D helix: hardened steel up to 65 HRC)"}, {"code": "EA", "meaning": "Slot drill heads for machining aluminum (CF: different helix)"}, {"code": "ERA", "meaning": "Rough milling heads for aluminum at high metal removal rates"}, {"code": "ERS", "meaning": "Rough milling heads for high metal removal rates"}, {"code": "EFS", "meaning": "Combined roughing and finishing (FINISHRED) heads"}, {"code": "ECK", "meaning": "5, 6 flute heads with different corner radii for titanium alloys (CHATTER-FREE)"}, {"code": "ECU", "meaning": "3 flute undersized heads for keyways (DIN 6885)"}, {"code": "EB", "meaning": "Ball nose milling heads"}, {"code": "EBA", "meaning": "High precision ball nose heads for aluminum"}, {"code": "EBC", "meaning": "Ball nose heads for high productivity on hard materials"}, {"code": "HC", "meaning": "Slot drill heads with two 10° helix flutes"}, {"code": "HCR", "meaning": "2 flute ball nose milling heads"}, {"code": "HRF", "meaning": "2 flute ball nose finishing heads"}, {"code": "HBR", "meaning": "2 flute high precision ball nose heads (240° spherical profile)"}, {"code": "HT", "meaning": "Toroidal 2 flute heads"}, {"code": "ETR", "meaning": "Toroidal 6 flute heads"}, {"code": "ET", "meaning": "Tapered heads for CHATTER-FREE finishing"}, {"code": "ELB", "meaning": "Lens-shaped (barrel) heads for 3D profiling"}, {"code": "ELBA", "meaning": "Lens-shaped (barrel) heads for 3D aluminum profiling"}, {"code": "EOB", "meaning": "Oval-shaped (barrel) heads for 3D profiling"}, {"code": "EOBA", "meaning": "Oval-shaped (barrel) heads for 3D aluminum profiling"}, {"code": "TS", "meaning": "T-slot, dovetail, circlip groove (DIN 471/472), 45° chamfering and double groove heads"}, {"code": "GRIT", "meaning": "Small diameter groove milling, 45° chamfering, dovetail and double-sided corner rounding heads"}, {"code": "HR", "meaning": "2 flute corner rounding heads"}, {"code": "ER", "meaning": "4 flute corner rounding heads"}, {"code": "HDF", "meaning": "2 flute heads for upper and bottom chamfering"}, {"code": "EPG", "meaning": "Single flute engraving heads"}, {"code": "FM", "meaning": "Face milling heads"}, {"code": "SS", "meaning": "Heads for involute spline shafts (DIN 5480)"}, {"code": "TRF", "meaning": "Partial profile thread milling heads (55° / 60°)"}, {"code": "TRD", "meaning": "Partial profile thread milling heads (60° metric / 55° Whitworth)"}, {"code": "MT", "meaning": "Thread milling heads with a MULTI-MASTER connection (ISO, UN, BSW)"}, {"code": "ESR", "meaning": "Solid carbide blank heads"}, {"code": "ESB", "meaning": "Solid carbide ball nose blank heads"}, {"code": "TC", "meaning": "Cemented carbide blank heads (slitting)"}]}, {"key": "t-dia", "title": "Head – diameter", "sample": "100", "rows": [{"code": "###", "meaning": "Cutting diameter x10 (e.g. 100 = 10 mm)"}, {"code": ".###", "meaning": "Cutting diameter in inches"}, {"code": "##", "meaning": "Diameter in mm (barrel and MT heads)"}]}, {"key": "t-helix", "title": "Head – helix", "sample": "A", "rows": [{"code": "A", "meaning": "30° helix"}, {"code": "B", "meaning": "45° helix"}, {"code": "C", "meaning": "10° helix"}, {"code": "D", "meaning": "50° helix (hardened steel)"}, {"code": "E", "meaning": "38° helix"}, {"code": "H", "meaning": "Different helix and variable pitch (CHATTER-FREE)"}, {"code": "N", "meaning": "Toroidal geometry (see the catalog)"}]}, {"key": "t-version", "title": "MT head – version", "rows": [{"code": "C", "meaning": "Version C (see the catalog)"}, {"code": "D", "meaning": "Version D (see the catalog)"}, {"code": "E", "meaning": "Version E (see the catalog)"}, {"code": "F", "meaning": "Version F (see the catalog)"}]}, {"key": "t-apmx", "title": "Head – cutting length", "sample": "07", "rows": [{"code": "##", "meaning": "Cutting length in mm (FM heads: x10)"}]}, {"key": "t-corner", "title": "Head – corner", "sample": "R1.0", "rows": [{"code": "R000", "meaning": "Sharp corner"}, {"code": "R#.#", "meaning": "Corner radius in mm"}, {"code": "R##", "meaning": "Corner radius x10 (e.g. R05 = 0.5 mm)"}, {"code": "R###", "meaning": "Corner radius x100 (e.g. R020 = 0.2 mm)"}, {"code": "C#", "meaning": "Corner chamfer x10 (e.g. C3 = 0.3 mm)"}, {"code": "C##", "meaning": "Corner chamfer x10 (e.g. C01 = 0.1 mm)"}]}, {"key": "t-width", "title": "Head – groove width", "rows": [{"code": "##", "meaning": "Groove width x10 mm"}, {"code": "###", "meaning": "Groove width x100 mm"}]}, {"key": "t-depth", "title": "Head – groove depth", "rows": [{"code": "T###", "meaning": "Groove depth x100 mm"}]}, {"key": "t-profile", "title": "Head – profile", "rows": [{"code": "N", "meaning": "T-slot head (see the catalog)"}, {"code": "H", "meaning": "T-slot head with corner radii (see the catalog)"}, {"code": "M60", "meaning": "60° metric partial profile"}, {"code": "W55", "meaning": "55° Whitworth partial profile"}, {"code": "ISO", "meaning": "ISO metric thread"}, {"code": "UN", "meaning": "UN thread"}, {"code": "W", "meaning": "55° BSW thread"}]}, {"key": "t-pitch", "title": "Head – thread pitch", "rows": [{"code": "#.#", "meaning": "Pitch in mm or threads per inch"}]}, {"key": "t-size", "title": "Head – size", "rows": [{"code": "##", "meaning": "Head size, about the diameter in mm (e.g. GRIT22 = 21.7 mm)"}]}, {"key": "t-module", "title": "Head – module", "rows": [{"code": "M###", "meaning": "Module x100"}]}, {"key": "t-teeth", "title": "Head – teeth range", "rows": [{"code": "Z####", "meaning": "Number of teeth range"}]}, {"key": "t-angle", "title": "Head – angle", "rows": [{"code": "##", "meaning": "Angle in degrees"}, {"code": "###", "meaning": "Angle in degrees"}]}, {"key": "t-grade", "title": "Head – variant", "rows": [{"code": "K", "meaning": "GRIT version K (see the catalog)"}, {"code": "P", "meaning": "GRIT version P (see the catalog)"}, {"code": "G", "meaning": "Blank version G (see the catalog)"}, {"code": "F", "meaning": "Blank version F (see the catalog)"}, {"code": "A", "meaning": "Version A (see the catalog)"}, {"code": "D", "meaning": "Version D (see the catalog)"}, {"code": "U", "meaning": "Version U (see the catalog)"}]}, {"key": "t-dims", "title": "Head – dimension code", "rows": [{"code": "…", "meaning": "Further dimension code (see the catalog)"}]}, {"key": "t-flutes", "title": "Head – flutes", "rows": [{"code": "#", "meaning": "Number of flutes"}, {"code": "##", "meaning": "Number of flutes"}]}, {"key": "t-connection", "title": "MULTI-MASTER connection", "sample": "T06", "rows": [{"code": "T##", "meaning": "MULTI-MASTER thread connection size (T04 – T21)"}]}, {"key": "t-suffix", "title": "Head – suffix", "rows": [{"code": "CF", "meaning": "CHATTER-FREE (different helix and variable pitch)"}, {"code": "H", "meaning": "With a central coolant hole"}, {"code": "I", "meaning": "With coolant holes directed to each flute"}, {"code": "H2", "meaning": "Coolant version H2 (see the catalog)"}, {"code": "C", "meaning": "Version C (see the catalog)"}, {"code": "NECK", "meaning": "With a neck"}]}, {"key": "s-family", "title": "Shank / accessory – type", "sample": "S-A", "rows": [{"code": "S-A", "meaning": "Cylindrical shank (straight or stepped), or integral adaptation shank (ER, HSK, BT, CAMFIX)"}, {"code": "S-B", "meaning": "85° conical shank"}, {"code": "S-D", "meaning": "89° conical shank"}, {"code": "TS-A", "meaning": "Shank for T-slot heads"}, {"code": "TS2-A", "meaning": "Shank for T-slot heads (TS2)"}, {"code": "GRT", "meaning": "Shank for GRIT slitting and grooving heads"}, {"code": "CAB", "meaning": "Extension (FLEX-FIT thread) or reducer (MULTI-MASTER to a smaller MULTI-MASTER)"}, {"code": "KEY", "meaning": "Clamping key"}, {"code": "WRENCH", "meaning": "Clamping wrench"}, {"code": "EGR", "meaning": "Adjustable torque handle"}]}, {"key": "s-length", "title": "Shank – overall length", "rows": [{"code": "L###", "meaning": "Overall length in mm"}]}, {"key": "s-reach", "title": "Shank – length to the head", "rows": [{"code": "##", "meaning": "Length to the head in mm"}, {"code": "###", "meaning": "Length to the head in mm"}]}, {"key": "s-shank", "title": "Shank – type", "rows": [{"code": "C", "meaning": "Cylindrical"}, {"code": "W", "meaning": "Weldon"}, {"code": "SL", "meaning": "Safe-Lock (by Haimer), helical grooves that prevent pull-out"}]}, {"key": "s-dia", "title": "Shank – diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm"}]}, {"key": "s-adaptation", "title": "Shank – adaptation", "rows": [{"code": "ER##", "meaning": "ER collet adaptation"}, {"code": "HSK A##", "meaning": "HSK adaptation"}, {"code": "BT##", "meaning": "BT adaptation"}, {"code": "C#", "meaning": "CAMFIX (ISO 26623-1) adaptation"}]}, {"key": "s-suffix", "title": "Shank – suffix", "rows": [{"code": "C", "meaning": "Carbide shank"}, {"code": "W", "meaning": "Tungsten (heavy metal) shank"}, {"code": "H", "meaning": "With coolant supply (inferred)"}, {"code": "AV", "meaning": "Anti-vibration shank"}, {"code": "B", "meaning": "Cylindrical shank which may be shortened"}, {"code": "N", "meaning": "Version N (see the catalog)"}]}, {"key": "s-size", "title": "Accessory – size", "rows": [{"code": "…", "meaning": "Key or wrench size"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
